test_input = [
    [6, 6, 2, 0, 9, 6, 4, 7, 8, 9, 9, 9],
    [2, 0, 4, 2, 6, 5, 7, 6, 9, 3, 9, 8],
    [2, 1, 0, 1, 4, 7, 9, 5, 9, 9, 9, 6],
    [0, 2, 1, 6, 7, 6, 5, 4, 9, 8, 6, 3]
]

def window_diversity(window):
    return len(set(val for row in window for val in row))

best_score = -1
best_cols = None

for start_col in range(12 - 4):
    window = [[row[start_col:start_col+5] for col_idx in range(len(row))] for row in test_input[:5]]
    score = window_diversity(window)
    if score > best_score:
        best_score = score
        best_cols = list(range(start_col, start_col + 5))

print(f"Best cols: {best_cols}, diversity={best_score}")
window = [row[best_cols[0]:best_cols[-1]+1] for row in test_input[:5]]
for row in window:
    print(row)

test_input = [
    [6, 6, 2, 0, 9, 6, 4, 7, 8, 9, 9, 9],
    [2, 0, 4, 2, 6, 5, 7, 6, 9, 3, 9, 8],
    [2, 1, 0, 1, 4, 7, 9, 5, 9, 9, 9, 6],
    [0, 2, 1, 6, 7, 6, 5, 4, 9, 8, 6, 3]
]

# Analyze how each column changes from row to row
print("Column changes between rows:")
for j in range(12):
    col = [test_input[i][j] for i in range(4)]
    changes = []
    for k in range(3):
        if col[k+1] != col[k]:
            changes.append((k, col[k], col[k+1]))
    print(f"Col {j}: {col}, changes={changes}")

# Maybe select cols where there's maximum variation?
def variation(col):
    return sum(abs(col[i+1] - col[i]) for i in range(len(col)-1))

print("\nColumn variations:")
variations = [(j, [test_input[i][j] for i in range(4)], variation([test_input[i][j] for i in range(4)])) for j in range(12)]
sorted_vars = sorted(variations, key=lambda x: x[2], reverse=True)
for j, col, v in sorted_vars[:7]:
    print(f"Col {j}: variance={v}, values={col}")

